public class DocumentChunk
{
    public int Index { get; set; }
    public string Text { get; set; } = string.Empty;
    public int EstimatedTokens { get; set; }
    public string? HeaderBreadcrumb { get; set; }
}

public class RecursiveTokenChunker
{
    private readonly int _maxTokens;
    private readonly int _overlapTokens;
    private static readonly string[] Separators = ["\n\n", "\n", ". ", ", ", " "];

    public RecursiveTokenChunker(int maxTokens = 500, int overlapTokens = 75)
    {
        _maxTokens = maxTokens;
        _overlapTokens = overlapTokens;
    }

    public List<DocumentChunk> ChunkDocument(string text, string? breadcrumb = null)
    {
        var chunks = new List<DocumentChunk>();
        var paragraphs = text.Split(new[] { "\n\n" }, StringSplitOptions.RemoveEmptyEntries);
        var currentChunkBuilder = new StringBuilder();
        int chunkIndex = 0;

        foreach (var paragraph in paragraphs)
        {
            var paragraphTokens = EstimateTokenCount(paragraph);

            // If paragraph fits in current chunk, append it
            if (EstimateTokenCount(currentChunkBuilder.ToString()) + paragraphTokens <= _maxTokens)
            {
                currentChunkBuilder.AppendLine(paragraph);
            }
            else
            {
                // Flush previous chunk if not empty
                if (currentChunkBuilder.Length > 0)
                {
                    chunks.Add(CreateChunk(chunkIndex++, currentChunkBuilder.ToString(), breadcrumb));

                    // Capture trailing overlap text
                    var overlapText = ExtractOverlap(currentChunkBuilder.ToString(), _overlapTokens);
                    currentChunkBuilder.Clear();
                    currentChunkBuilder.AppendLine(overlapText);
                }

                currentChunkBuilder.AppendLine(paragraph);
            }
        }

        if (currentChunkBuilder.Length > 0)
        {
            chunks.Add(CreateChunk(chunkIndex, currentChunkBuilder.ToString(), breadcrumb));
        }

        return chunks;
    }

    private static DocumentChunk CreateChunk(int index, string content, string? breadcrumb)
    {
        return new DocumentChunk
        {
            Index = index,
            Text = content.Trim(),
            EstimatedTokens = EstimateTokenCount(content),
            HeaderBreadcrumb = breadcrumb
        };
    }

    private static int EstimateTokenCount(string s) => (int)Math.Ceiling(s.Length / 4.0);

    private static string ExtractOverlap(string text, int overlapTokens)
    {
        var words = text.Split(' ');
        int targetWords = (int)(overlapTokens * 0.75);
        if (words.Length <= targetWords) return text;
        return string.Join(" ", words.TakeLast(targetWords));
    }
}
